	@Test void all102DefinitionsConstructWithOnlyJdkAndKeepEveryFrozenEffectiveValue(){
		assertEquals(102,SpellDefinition.ALL.size());assertEquals(102,SpellDefinition.ALL.stream().map(SpellDefinition::id).distinct().count());
		for(int i=0;i<BASELINE.size();i++){
			var e=BASELINE.get(i);var a=SpellDefinition.ALL.get(i);
			assertEquals(e.id,a.id());assertSame(a,SpellDefinition.find(e.id));assertEquals(e.mana,a.manaCost());assertEquals(e.damage,a.damage());assertEquals(e.recovery,a.cooldownTicks());assertEquals(e.lifetime,a.lifetimeTicks());assertEquals(e.element,a.element());assertEquals((float)e.speed,a.speed());assertEquals(e.gravity,a.gravity());assertEquals(e.knockback,a.knockback());assertEquals(e.castMode,a.castMode().name());assertEquals(e.requirements,a.requirements());assertEquals(e.execution,a.execution().name());assertEquals(e.healing,a.healing());assertEquals(e.range,a.range());assertEquals(e.maxTargets,a.maxTargets());assertEquals(e.learning,a.learningRequirements());assertEquals(e.rank,a.rank());assertEquals(e.graded,a.officiallyGraded());assertEquals(e.preparation,a.castingProfile().preparationTicks());assertEquals(e.profileRecovery,a.castingProfile().recoveryTicks());assertEquals(e.circle,a.castingProfile().requiresCircle());assertEquals(e.motion,a.motion().name());assertEquals(e.category,MagicCategory.of(a).name());assertEquals(e.flightTicks,a.flightTicks());assertEquals(e.flightRange,Double.toString(a.flightRange()));assertEquals(e.piercing,a.piercing());assertEquals(e.area,a.areaDamage());assertEquals(e.status,a.statusTicks());assertEquals(e.icy,a.icy());assertEquals(e.color,a.glowColor());assertEquals(e.officialRank,a.officialRank());
		}
		assertNull(SpellDefinition.find("unknown"));
	}
	@Test void builderProducesIndependentImmutableValidatedProducts(){
		var prerequisites=new java.util.ArrayList<>(java.util.List.of("water_ball"));
		var builder=SpellDefinition.builder("test").manaCost(4).damage(3).lifetimeTicks(20).execution(SpellDefinition.Execution.PHASE_TWO).learningRequirements(prerequisites);
		var first=builder.build();prerequisites.add("ice_smash");var second=builder.manaCost(8).timingRank(3).build();
		assertEquals(4,first.manaCost());assertEquals(8,second.manaCost());assertEquals(2,first.rank());assertEquals(3,second.rank());assertEquals(java.util.List.of("water_ball"),first.learningRequirements());assertThrows(UnsupportedOperationException.class,()->first.learningRequirements().add("fireball"));
		assertThrows(IllegalArgumentException.class,()->SpellDefinition.builder("invalid").manaCost(-1).build());
		assertThrows(IllegalArgumentException.class,()->SpellDefinition.builder("invalid").timingRank(8).build());
	}
